// EPMS: Teams link preview test.
// Serves a page with Open Graph tags at /preview/test so we can see what card Teams builds.
routerAdd("GET", "/preview/test", (e) => {
  const now = new Date().toISOString()
  const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Innovation Management: 1 task in review</title>
<meta name="description" content="Jimmy is blocked by Find 5 sources. Final deadline Friday.">
<meta property="og:type" content="website">
<meta property="og:site_name" content="EPMS">
<meta property="og:title" content="Innovation Management: 1 task in review">
<meta property="og:description" content="Jimmy is blocked by Find 5 sources. Final deadline Friday.">
</head>
<body style="font-family: system-ui; padding: 2rem">
<h1>EPMS preview test</h1>
<p>Generated by the server at ${now}.</p>
</body>
</html>`
  return e.html(200, html)
})
